import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, calculateDueDate } from './dates.js';


/**
 * Validate a discount percent value.
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscountPercent(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate the total for a line item (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the VAT for a line item (computed on amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = roundCents(total * (line.discountPercent || 0) / 100);
  const amountAfterDiscount = total - discount;
  return roundCents(amountAfterDiscount * line.vatRate / 100);
}

/**
 * Apply a voucher to an invoice (takes amount off after VAT).
 * @param {object} invoice
 * @param {{ code: string, amount: number }} voucher code and amount in cents
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check voucher doesn't already exist
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  const newInvoice = {
    ...invoice,
    voucher: { code, amount },
  };

  return ok(newInvoice);
}

/**
 * Calculate the totals for an invoice (subtotal, discount, VAT, voucher, and total).
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const lineDiscount = roundCents(lineTotal(line) * (line.discountPercent || 0) / 100);
    return sum + lineDiscount;
  }, 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Create an invoice with the given customer, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} opts
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) return fail('TERMS_INVALID');

  // Calculate due date
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Get customer data for tier discount
  const customer = customerResult.value;

  // Build invoice lines with product data
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount percent
    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate sku exists
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    // Use explicit discountPercent if provided, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    dueDate,
    terms,
    status: 'draft',
    lines: invoiceLines,
  };

  return ok(invoice);
}

